package org.apache.commons.math.stat.descriptive;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.StorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.stat.descriptive.univariate.GeometricMean;
import org.apache.commons.math.stat.descriptive.univariate.Mean;
import org.apache.commons.math.stat.descriptive.univariate.Variance;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class SummaryStatistics_addValue_TriageGen4Test {

    private SummaryStatistics summaryStatistics;

    @Before
    public void setUp() {
        summaryStatistics = new SummaryStatistics();
    }

    @Test
    public void testAddValue_StandardFlow() {
        // Test basic functionality with default implementations
        double value = 10.0;
        summaryStatistics.addValue(value);

        assertEquals(1, summaryStatistics.getN());
        assertEquals(value, summaryStatistics.getSum(), 1e-10);
        assertEquals(value * value, summaryStatistics.getSumsq(), 1e-10);
        assertEquals(value, summaryStatistics.getMean(), 1e-10);
        assertEquals(value, summaryStatistics.getMax(), 1e-10);
        assertEquals(value, summaryStatistics.getMin(), 1e-10);
        assertEquals(value, summaryStatistics.getSumOfLogs(), Math.log(value));
        assertEquals(value * value, summaryStatistics.getSecondMoment(), 1e-10);
        // Variance of a single element is technically undefined/0 depending on implementation, 
        // but we check if it updated without crashing.
    }

    @Test
    public void testAddValue_MultipleValues() {
        summaryStatistics.addValue(2.0);
        summaryStatistics.addValue(4.0);

        assertEquals(2, summaryStatistics.getN());
        assertEquals(6.0, summaryStatistics.getSum(), 1e-10);
        assertEquals(20.0, summaryStatistics.getSumsq(), 1e-10); // 4 + 16
        assertEquals(3.0, summaryStatistics.getMean(), 1e-10);
        assertEquals(4.0, summaryStatistics.getMax(), 1e-10);
        assertEquals(2.0, summaryStatistics.getMin(), 1e-10);
    }

    @Test
    public void testAddValue_WithOverriddenMean() {
        // To maximize branch coverage, we need to trigger the 'if (!(meanImpl instanceof Mean))' condition.
        // We do this by providing a custom implementation that is NOT an instance of Mean.

        StorelessUnivariateStatistic mockMean = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockVariance = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockGeoMean = mock(StorelessUnivariateStatistic.class);

        // Mocking the other required components to avoid NullPointerException
        StorelessUnivariateStatistic sumImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic sumsqImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic minImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic maxImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic sumLogImpl = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic secondMomentImpl = mock(StorelessUnivariateStatistic.class);

        summaryStatistics.setSumImpl(sumImpl);
        summaryStatistics.setSumsqImpl(sumsqImpl);
        summaryStatistics.setMinImpl(minImpl);
        summaryStatistics.setMaxImpl(maxImpl);
        summaryStatistics.setSumLogImpl(sumLogImpl);
        summaryStatistics.setMeanImpl(mockMean); // Not an instance of Mean
        summaryStatistics.setVarianceImpl(mockVariance); // Not an instance of Variance
        summaryStatistics.setGeoMeanImpl(mockGeoMean); // Not an instance of GeometricMean

        // We need to handle the secondMoment field which is accessed directly in the code
        // Note: In the provided source, secondMoment.increment(value) is called.
        // Since we can't set secondMoment through a setter in the snippet, 
        // we assume it's initialized or we must use a subclass if it were a protected field.
        // However, based on the provided code, we will test the logic branches.

        double val = 5.0;
        summaryStatistics.addValue(val);

        // Verify that increment was called on the custom mocks because they are NOT instances of the specific classes
        verify(mockMean, times(1)).increment(val);
        verify(mockVariance, times(1)).increment(val);
        verify(mockGeoMean, times(1)).increment(val);
        verify(sumImpl, times(1)).increment(val);
    }

    @Test
    public void testAddValue_WithSpecificTypeImplementations() {
        // To cover the 'else' branch (where the condition is false), 
        // the implementations must be instances of Mean, Variance, and GeometricMean.

        // We use real objects that inherit from the target classes to satisfy 'instanceof'
        Mean realMean = new Mean();
        Variance realVariance = new Variance();
        GeometricMean realGeoMean = new GeometricMean();

        summaryStatistics.setMeanImpl(realMean);
        summaryStatistics.setVarianceImpl(realVariance);
        summaryStatistics.setGeoMeanImpl(realGeoMean);

        // We use spies to verify that increment is NOT called on these specific objects 
        // by the logic inside addValue (because the 'if' condition fails).
        // However, the addValue method calls increment on them via the 'if' block.
        // Wait, looking at the logic: if (!(meanImpl instanceof Mean)) { meanImpl.increment(value); }
        // If meanImpl IS an instance of Mean, the increment is SKIPPED.

        Mean spyMean = spy(new Mean());
        Variance spyVariance = spy(new Variance());
        GeometricMean spyGeoMean = spy(new GeometricMean());

        summaryStatistics.setMeanImpl(spyMean);
        summaryStatistics.setVarianceImpl(spyVariance);
        summaryStatistics.setGeoMeanImpl(spyGeoMean);

        double val = 1.0;
        summaryStatistics.addValue(val);

        // Verification: Since they ARE instances of the classes, increment should NOT be called by the if-blocks
        verify(spyMean, never()).increment(val);
        verify(spyVariance, never()).increment(val);
        verify(spyGeoMean, never()).increment(val);
    }
}
